// ─── SUPABASE MAPPERS ─────────────────────────────────────────────────────────
// The database uses snake_case; the UI below expects camelCase. Every row that
// crosses that boundary goes through one of these.

const mapMember = (r) => ({
  id: r.id,
  authUserId: r.auth_user_id,
  name: r.name,
  email: r.email,
  role: r.role,                       // 'player' | 'committee' | 'administrator'
  handicap: r.handicap ?? 0,
  aguHandicap: r.agu_handicap,
  active: r.active,
});

const mapHole = (h) => ({
  number: h.hole_number,
  par: h.par,
  meters: h.meters,
  strokeIndex: h.stroke_index,
});

const mapCourse = (c) => ({
  id: c.id,
  name: c.name,
  location: c.location ?? "",
  address: c.address ?? "",
  rating: c.course_rating,
  slope: c.slope_rating,
  par: c.par,
  holes: (c.holes ?? []).slice().sort((a, b) => a.hole_number - b.hole_number).map(mapHole),
});

const mapEvent = (e) => ({
  id: e.id,
  date: e.event_date,
  courseId: e.course_id,
  teeTime: (e.tee_time ?? "").slice(0, 5),
  format: e.format ?? "stableford",
  notes: e.notes ?? "",
});

const mapRound = (r, nameById = {}) => ({
  id: r.id,
  userId: r.member_id,
  userName: nameById[r.member_id] ?? "",
  courseId: r.course_id,
  courseName: r.courses?.name ?? "",
  courseRating: r.courses?.course_rating ?? null,
  courseSlope: r.courses?.slope_rating ?? null,
  coursePar: r.courses?.par ?? null,
  scheduleEventId: r.schedule_event_id,
  date: r.played_at,
  format: r.format ?? "stableford",
  gross: r.gross_score,
  net: r.net_score,
  stableford: r.stableford_points,
  dailyHcp: r.daily_handicap,
  scoreDiff: r.score_differential,
  isHistorical: r.is_historical,
  scores: Object.fromEntries((r.hole_scores ?? []).map(h => [h.hole_number, String(h.gross_score)])),
});

// Permission helper — the database enforces these too, via RLS.
const isAdminUser = (u) => u?.role === "administrator";
const isCommitteeUser = (u) => u?.role === "committee" || u?.role === "administrator";

// ─── HELPERS ──────────────────────────────────────────────────────────────────
function getDailyHandicap(h,cr,par,sl){return Math.round(h*(sl/113)+(cr-par));}
function getStrokesReceived(dh,si){if(dh<=0)return 0;if(dh>=si)return Math.floor(dh/18)+1;return Math.floor(dh/18);}
function calcStableford(g,par,sr){const n=g-par-sr;if(n<=-2)return 4;if(n===-1)return 3;if(n===0)return 2;if(n===1)return 1;return 0;}
function calcScoreDiff(g,cr,sl){return((g-cr)*113)/sl;}
function calcAGUHandicap(rounds){
  const last20=[...rounds].sort((a,b)=>new Date(a.date)-new Date(b.date)).slice(-20);
  const diffs=last20.map(r=>r.scoreDiff).sort((a,b)=>a-b);
  const n=diffs.length;if(n<3)return null;
  const table=[[3,1],[4,1],[5,2],[6,2],[7,3],[8,3],[9,4],[10,4],[11,4],[12,5],[13,5],[14,5],[15,6],[16,6],[17,7],[18,7],[19,8],[20,8]];
  const row=table.find(([x])=>x===n)||table[table.length-1];
  const best=diffs.slice(0,row[1]);
  return Math.max(0,parseFloat((best.reduce((s,d)=>s+d,0)/row[1]*0.96).toFixed(1)));
}
function fmtDate(d){return new Date(d+"T12:00:00").toLocaleDateString("en-AU",{weekday:"short",day:"numeric",month:"short",year:"numeric"});}
function fmtDateShort(d){return new Date(d+"T12:00:00").toLocaleDateString("en-AU",{day:"numeric",month:"short"});}
function isToday(d){return new Date(d+"T12:00:00").toDateString()===new Date().toDateString();}
function isPast(d){return new Date(d+"T12:00:00")<new Date(new Date().toDateString());}
function isFuture(d){return new Date(d+"T12:00:00")>new Date();}
function daysUntil(d){return Math.ceil((new Date(d+"T12:00:00")-new Date())/86400000);}

